#!/usr/bin/env node

const fs = require("fs");
const path = require("path");
const os = require("os");

const VERSION = "1.1.3";
const NAME = "grill-game-design";
const SKILLS = ["grill-me-game-design", "grill-me-game-dev"];

function parseArgs(argv) {
  const args = { target: null, scope: "project", help: false, version: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--target" && argv[i + 1]) args.target = argv[++i].toLowerCase();
    else if (a === "--scope" && argv[i + 1]) args.scope = argv[++i].toLowerCase();
    else if (a === "--help" || a === "-h") args.help = true;
    else if (a === "--version" || a === "-v") args.version = true;
  }
  return args;
}

function help() {
  console.log(`
🔥 ${NAME}

Instala as Skills do Grill no ambiente do aluno.

Uso:
  npx grill-game-design
  npx grill-game-design --target copilot
  npx grill-game-design --target claude
  npx grill-game-design --target cursor
  npx grill-game-design --target codex

Opções:
  --target <copilot|claude|cursor|codex>
  --scope <project|global>   padrão: project
  --version
  --help

O modo interativo instala somente a integração escolhida.
`);
}

function copyDir(src, dest) {
  fs.mkdirSync(dest, { recursive: true });
  fs.cpSync(src, dest, { recursive: true });
}

function findProjectRoot() {
  let dir = process.cwd();
  while (true) {
    if (fs.existsSync(path.join(dir, ".git")) || fs.existsSync(path.join(dir, "package.json"))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) return process.cwd();
    dir = parent;
  }
}

function skillSource(name) {
  return path.resolve(__dirname, "..", "skill", name);
}

function skillTargets(target, scope, root) {
  const home = os.homedir();
  const base = scope === "global" ? home : root;
  const project = scope === "global" ? home : root;
  const dirs = {
    copilot: path.join(project, ".github", "skills"),
    claude: path.join(project, ".claude", "skills"),
    codex: path.join(project, ".agents", "skills")
  };
  return dirs[target];
}

function install(target, scope, root) {
  const installed = [];

  if (target === "cursor") {
    const skillBase = scope === "global"
      ? path.join(os.homedir(), ".agents", "skills")
      : path.join(root, ".agents", "skills");
    const rulesBase = scope === "global"
      ? path.join(os.homedir(), ".cursor", "rules")
      : path.join(root, ".cursor", "rules");

    for (const name of SKILLS) {
      const dest = path.join(skillBase, name);
      copyDir(skillSource(name), dest);
      const rel = path.relative(root, dest).replaceAll("\\", "/");
      fs.mkdirSync(rulesBase, { recursive: true });
      const rule = "---\ndescription: " + name + "\nalwaysApply: false\n---\n\nConsulte a Skill em `" + rel + "/SKILL.md`.\n";
      fs.writeFileSync(path.join(rulesBase, `${name}.mdc`), rule, "utf8");
      installed.push(`Cursor → ${path.join(rulesBase, `${name}.mdc`)}`);
    }
    return installed;
  }

  const base = skillTargets(target, scope, root);
  for (const name of SKILLS) {
    const dest = path.join(base, name);
    copyDir(skillSource(name), dest);
    installed.push(`${target} → ${dest}`);
  }
  return installed;
}

async function chooseTarget() {
  const options = [
    ["copilot", "GitHub Copilot"],
    ["claude", "Claude Code"],
    ["cursor", "Cursor"],
    ["codex", "Codex"]
  ];

  console.log("Qual agente você está usando?\n");
  options.forEach(([key, label], i) => console.log(`  ${i + 1}. ${label}`));
  process.stdout.write("\nEscolha [1-4]: ");

  const answer = await new Promise((resolve) => {
    process.stdin.setEncoding("utf8");
    process.stdin.once("data", (data) => {
      resolve(data.trim());
      process.stdin.pause();
      process.stdin.removeAllListeners("data");
    });
  });

  const index = Number(answer) - 1;
  if (Number.isInteger(index) && index >= 0 && index < options.length) return options[index][0];
  throw new Error("Escolha inválida. Execute o comando novamente e escolha uma opção de 1 a 4.");
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) return help();
  if (args.version) return console.log(VERSION);

  const valid = ["copilot", "claude", "cursor", "codex"];
  if (args.target && !valid.includes(args.target)) {
    console.error(`Agente inválido: ${args.target}`);
    process.exit(1);
  }

  if (args.scope !== "project" && args.scope !== "global") {
    console.error(`Scope inválido: ${args.scope}`);
    process.exit(1);
  }

  const root = findProjectRoot();
  const target = args.target || await chooseTarget();

  console.log(`\n🔥 ${NAME} v${VERSION}\n`);
  console.log(`Projeto: ${root}`);
  console.log(`Destino: ${args.scope}`);
  console.log(`Agente:  ${target}\n`);

  const installed = install(target, args.scope, root);
  console.log("✓ Skills instaladas:\n");
  installed.forEach((item) => console.log(`  ${item}`));

  console.log(`\n✓ Pronto.\n\nPróximos comandos no agente:\n  /grill-me-game-design\n  /grill-me-game-dev\n`);
  process.stdin.pause();
}

main().catch((err) => {
  console.error("\n✗ Não foi possível instalar as Skills.");
  console.error(err.message);
  process.exit(1);
});
